use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-two-chain-stream176";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let state:Value=serde_json::from_slice(&fs::read(format!("{R}/native/result.json")).unwrap()).unwrap();assert_eq!(state["status"],"complete");assert!(!Path::new(R).join("candidate-bin").exists());let log=fs::read_to_string(format!("{R}/native/driver-build/stderr.log")).unwrap();let line=log.lines().find(|l|l.contains("Running")&&l.contains("--crate-name zopro_two_chain_stream")).unwrap();for flag in["-C opt-level=3","-C target-cpu=native","-C lto=fat","-C codegen-units=1","--cfg zopro_two_chain_stream"]{assert!(line.contains(flag),"{flag}");}let core=fs::read_to_string(format!("{R}/native/core-tests/stdout.log")).unwrap();assert!(core.contains("128 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out"));let source=format!("{R}/target/release/zopro-two-chain-stream");let binary=format!("{R}/candidate-bin");fs::copy(&source,&binary).unwrap();assert_eq!(hash(&source),hash(&binary));let id=json!({"binary":binary,"binary_sha256":hash(&source),"actual_rustc":line,"kind":"diagnostic ordinary G2 batch caller; not accepted SDK","native_workflow_commands":3,"native_core_tests_passed":128,"new_native_tests":3,"timing_started":false,"original_driver_exact":true});let value=json!({"OFF":id,"ON":id});fs::write(format!("{R}/identities.json"),serde_json::to_vec_pretty(&value).unwrap()).unwrap();println!("{}",json!({"frozen":binary,"sha256":hash(&source),"native_optimized_flags_verified":true,"no_timing":true}));}
